// Generated by vibelang from plugins/bugs/src/tab.vibe; the migrate flow writes it again with each batch.
export { FORM, MAX_WHAT, idFor, settle, tab, whatOf } from "./tab.vibe.platform.js";
/** The inbox's view. */
export const INBOX = "bugs/inbox";
/** Why a report wasn't sent, in a few words, from its failure's code. */
export const reasonOf = (code) => {
    switch (code) {
        case "authentication":
            return "signed out";
        case "forbidden":
            return "not allowed";
        case "invalid":
        case "invalid_fields":
            return "not accepted";
        case "too_large":
            return "too long";
        case "BugUnsent":
            return "couldn't reach Smithers";
        default:
            return code;
    }
};
